"""Render documentation from executed result files; never synthesize measurements."""
import json
import statistics
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
pg=json.loads((ROOT/"benchmarks/results/postgres.json").read_text(encoding="utf-8"))
sqlite=json.loads((ROOT/"benchmarks/results/sqlite.json").read_text(encoding="utf-8"))
perf=json.loads((ROOT/"benchmarks/results/http-performance.json").read_text(encoding="utf-8"))

def pct(value):return "n/a" if value is None else f"{value*100:.2f}%"
def label(run):return "Original lexical" if run["provider"].startswith("lexical") else "MiniLM semantic"
first_cases=pg["runs"][0]["cases"]
calibration_count=sum(c["split"]=="calibration" for c in first_cases)
evaluation_count=sum(c["split"]=="evaluation" for c in first_cases)
candidate_count=sum(c["split"]=="candidate" for c in first_cases)
candidate_supported=sum(c["split"]=="candidate" and c["metrics"]["recall_at_5"] is not None for c in first_cases)
human_count=sum(c["split"]=="human_approved" for c in first_cases)
pg_lex=next(r for r in pg["runs"] if r["provider"].startswith("lexical") and r["strategy"]=="hybrid")
pg_sem=next(r for r in pg["runs"] if r["provider"]=="semantic" and r["strategy"]=="hybrid")
lines=["# Executed RAG benchmarks", "", "These are measured results on a deliberately authored synthetic corpus, **not independently human-verified accuracy estimates**. The fixtures were inspected during development and used to fix failures; the evaluation split is a regression set, not a blind holdout. Candidate labels remain unverified. No paid AI calls were used.", "", "## Dataset and protocol", "", f"The same {pg['source_count']} source documents and {pg['case_count']} questions were used for both providers: {calibration_count+evaluation_count} deterministic fixture contracts ({calibration_count} calibration, {evaluation_count} regression/evaluation), plus {candidate_count} unverified review candidates. {candidate_supported} candidates contain proposed source quotes; {candidate_count-candidate_supported} have no supporting source. Human-approved cases in this run: {human_count}.", "", "Sources cover exact matches, paraphrases, synonyms, multiple documents, similar plans with conflicting limits, conflicting legacy policies, unanswerable/adversarial requests, a long operations manual, repeated token terminology and facts from different sections. Source references identify both a document and an exact expected passage. Retrieving the right document's wrong chapter does not count as relevant evidence.", "", "The original retrieval and answer baseline is frozen from main commit `ad103d5` in `benchmarks/baseline.py`. It retains lexical hashing, original AND full-text matching and original lexical answer selection. The new pipeline uses real CPU MiniLM vectors, token-budget-aware chunks, OR full-text matching, semantic evidence gates, weighted reciprocal rank fusion and stronger grounding. Therefore end-to-end differences include those engineering changes; vector-only comparisons are the clearest evidence of the embedding improvement. Both modes indexed 28 chunks for this particular corpus; longer-token inputs are separately covered by token-budget tests.", "", "Model: `sentence-transformers/all-MiniLM-L6-v2`, ONNX revision `d13954661f83248295ba75c1ed411eef3b7b936e`, 384 dimensions, 256-token budget, attention-mask mean pooling and L2 normalization. Two CPU threads, batch size 32, bounded in-memory vector cache. No fine-tuning, paid generation, reranker or agent orchestration. See SEMANTIC_MODELS.md for checksums/licensing.", "", f"PostgreSQL environment: `{pg['platform']}`, Python {pg['python']}, {pg['cpu_logical_count']} logical CPUs visible. SQLite environment: `{sqlite['platform']}`, Python {sqlite['python']}. These are local development-host measurements; concurrent browser/build activity can affect timing. Model files were already cached. Query order is seeded, the model remains warm and repeated queries/sentences may hit the bounded cache. Hardware, cache state and load change latency and memory.", "", "Hit@K means at least one expected passage is in the first K results. Recall@5 is the fraction of all expected evidence references retrieved, including multi-source questions. MRR@5 is reciprocal rank of the first expected passage, or zero if absent. Citation validity checks quote existence **and** attribution to an actually retrieved chunk. Refusal agreement includes qualified refusals for individual eligibility/time questions; it is not a general safety score. Citation validity averages only cases with citations. No semantic entailment score is claimed.", "", "## PostgreSQL/pgvector fixture regression results", "", "26 regression cases; retrieval metrics use the 24 cases with expected evidence. Citation/refusal metrics use their applicable labeled cases. The 4 calibration cases are reported separately in the raw files.", "", "| Provider | Strategy | Hit@1 | Hit@3 | Hit@5 | Recall@5 | MRR@5 | Citation provenance | Refusal agreement | Mean retrieval ms | Mean end-to-end ms |", "| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |"]
for run in pg['runs']:
 m=run['splits']['evaluation']['metrics'];lines.append(f"| {label(run)} | {run['strategy']} | {pct(m['hit_at_1'])} | {pct(m['hit_at_3'])} | {pct(m['hit_at_5'])} | {pct(m['recall_at_5'])} | {m['mrr']:.4f} | {pct(m['citation_validity'])} | {pct(m['refusal_correct'])} | {m['retrieval_latency_ms']:.2f} | {m['end_to_end_latency_ms']:.2f} |")
lines += ["", f"PostgreSQL hybrid fixture Hit@1 changed from {pct(pg_lex['splits']['evaluation']['metrics']['hit_at_1'])} to {pct(pg_sem['splits']['evaluation']['metrics']['hit_at_1'])}, and evidence Recall@5 from {pct(pg_lex['splits']['evaluation']['metrics']['recall_at_5'])} to {pct(pg_sem['splits']['evaluation']['metrics']['recall_at_5'])}. These finite fixture results describe this authored set; they do not establish general accuracy or performance on customer data.", "", "## SQLite fixture results", "", "| Provider | Strategy | Hit@1 | Hit@3 | Recall@5 | MRR@5 | Mean retrieval ms |", "| --- | --- | --- | --- | --- | --- | --- |"]
for run in sqlite['runs']:
 m=run['splits']['evaluation']['metrics'];lines.append(f"| {label(run)} | {run['strategy']} | {pct(m['hit_at_1'])} | {pct(m['hit_at_3'])} | {pct(m['recall_at_5'])} | {m['mrr']:.4f} | {m['retrieval_latency_ms']:.2f} |")
lines += ["", "SQLite semantic vector ranks outperformed hybrid ranks on this fixture set, while PostgreSQL hybrid benefited from full-text ranking/stemming. First-upload defaults therefore use semantic vector on SQLite and hybrid on PostgreSQL, preserving existing project selections. No backend-independent optimal strategy is claimed.", "", "## Unverified candidate comparison", "", "These are proposed-label diagnostics over all 120 candidates, **not verified ground truth or accuracy**. Retrieval denominators exclude the 20 candidates without proposed evidence. A human must review the source/answer labels before using them as a trusted evaluation set.", "", "| Provider | PostgreSQL strategy | Proposed Hit@1 | Proposed Recall@5 | Proposed MRR@5 | Proposed refusal agreement |", "| --- | --- | --- | --- | --- | --- |"]
for run in pg['runs']:
 m=run['splits']['candidate']['metrics'];lines.append(f"| {label(run)} | {run['strategy']} | {pct(m['hit_at_1'])} | {pct(m['recall_at_5'])} | {m['mrr']:.4f} | {pct(m['refusal_correct'])} |")
lines += ["", "The candidate set still exposes misses and refusal disagreement. Examples from the semantic hybrid run:", ""]
sem=next(r for r in pg['runs'] if r['provider']=='semantic' and r['strategy']=='hybrid')
failures=[c for c in sem['cases'] if c['split']=='candidate' and (c['metrics']['recall_at_5']==0 or c['metrics']['refusal_correct']==0)]
for c in failures[:4]:lines.append(f"* `{c['id']}`: {c['question']} Proposed recall={c['metrics']['recall_at_5']}; refusal agreement={c['metrics']['refusal_correct']}. This is a review candidate, not a confirmed model error.")
lines += ["", "## Required return-policy scenario", "", 'Source: “Customers may return eligible products within 30 calendar days of receiving their order.”', "", "The table uses the same full PostgreSQL corpus and hybrid retrieval, so related refund documents also compete. Ranks refer to this exact return-policy passage, not merely a related document.", "", "| Question | Original lexical evidence rank | Semantic evidence rank | Semantic outcome |", "| --- | --- | --- | --- |"]
lex=next(r for r in pg['runs'] if r['provider'].startswith('lexical') and r['strategy']=='hybrid')
ref='Customers may return eligible products within 30 calendar days of receiving their order.'
def evidence_rank(c):return next((str(i+1) for i,s in enumerate(c['retrieved']) if s['document']=='returns.md' and ref in s['text']),"not in top 5")
for i in range(1,6):
 a=next(c for c in lex['cases'] if c['id']==f'return-{i}');b=next(c for c in sem['cases'] if c['id']==f'return-{i}')
 outcome='Qualified refusal with exact source quotes' if b['refused'] and b['citations'] else 'Refusal without evidence' if b['refused'] else 'Exact source-policy excerpt'
 lines.append(f"| {b['question']} | {evidence_rank(a)} | {evidence_rank(b)} | {outcome} |")
lines += ["", "The assistant deliberately does not assert that a particular item qualifies, convert two weeks into an eligibility decision, or invent an exception after 45 days/six months. It supplies the explicit 30-day rule with a qualification. The real-model backend tests separately run all five questions with only the single required source.", "", "## Throughput and resources", "", "PostgreSQL indexing of the same 18 documents (28 chunks), warm model files:", "", "| Provider | Wall seconds | Documents/s | Characters/s | Embedding ms sum | Sampled peak index RSS MiB | Cached-file model init ms |", "| --- | --- | --- | --- | --- | --- | --- |"]
for run in [lex,sem]:
 m=run['indexing'];lines.append(f"| {label(run)} | {m['seconds']:.4f} | {m['documents_per_second']:.3f} | {m['characters_per_second']:.2f} | {m['embedding_ms_sum']:.2f} | {m['sampled_peak_rss_mb']:.2f} | {m['model_load_ms_cached_files']:.2f} |")
health=perf['health_during_indexing']
lines += ["", "RSS is sampled after indexing/query steps, not a guaranteed operating-system peak or total deployment memory. Each API/worker process owns a model session; batch arenas can retain memory after larger inputs. [Container observations](../benchmarks/results/container-resources.json) capture point-in-time Docker memory/CPU, not capacity limits.", "", f"The real HTTP test issued {perf['requests']} successful queries at concurrency {perf['concurrency']}: {perf['requests_per_second']:.3f} requests/s, median {perf['http_p50_ms']:.2f} ms, P95 {perf['http_p95_ms']:.2f} ms. It repeats three questions and leaves the cache enabled. All {len(health)} health requests returned 200; processing was observed before the burst. Their median was {statistics.median(x['ms'] for x in health):.2f} ms and maximum {max(x['ms'] for x in health):.2f} ms. Indexing can finish during the burst. Tail latency is noticeable; these results are not a production throughput guarantee.", "", "A 140,004-character repeated-manual upload in that test reports its actual indexing and embedding time in [http-performance.json](../benchmarks/results/http-performance.json). Repetition benefits deduplication, so it must not be presented as unique-corpus throughput. The first load harness exceeded the configured request budget through excessive status polling; it was corrected to respect that budget rather than raising the product limit.", "", "## Tuning and limitations", "", "The exploratory 0.32/0.40/0.48 threshold sweep is stored in [sqlite-calibration.json](../benchmarks/results/sqlite-calibration.json). Higher gates lost supported paraphrases. The 0.32 choice was made using these inspected synthetic fixtures, not an independent holdout. Equal fusion overweighted some vocabulary matches; semantic hybrid weights vector ranks 2 and keyword ranks 1. This remains a small deterministic heuristic, not a trained reranker.", "", "Observed grounding failures led to removing heading-only answers, preserving PDF soft-wrapped sentences, excluding instruction directives from evidence, narrowing numeric-conflict comparisons to similarly relevant passages and refusing instruction/exfiltration requests. Exact-quote provenance is checked, but a quote's existence does not establish truth, completeness or semantic entailment. Numeric conflict detection covers a narrow same-sentence pattern; general contradictions and complicated eligibility remain unresolved. Hosted adapters have contract tests only; no live paid-provider test was performed.", "", "## Reproduce and review", "", "```sh", "# From repository root, after dependency installation/model prefetch:", "python benchmarks/build_dataset.py", "python benchmarks/run.py --candidates --thresholds 0.32 --output benchmarks/results/local.json", "python benchmarks/run.py --candidates --thresholds 0.32,0.40,0.48 --output benchmarks/results/local-sweep.json", "python benchmarks/report.py", "```", "", "For PostgreSQL, create a dedicated disposable benchmark database, apply Alembic migrations, and set `DATABASE_URL`/`STORAGE_DIR` for that process. The runner creates uniquely named users/projects and removes only those records/files; never point tests that clear tables at an application's live database. The executed Docker command used:", "", "```sh", "docker compose -p ragforge-m2 exec -T db createdb -U ragforge ragforge_m2_benchmark", "docker compose -p ragforge-m2 exec -T -e DATABASE_URL=postgresql+psycopg://ragforge:local-ragforge-change-me@db:5432/ragforge_m2_benchmark api python -m alembic -c backend/alembic.ini upgrade head", "docker compose -p ragforge-m2 exec -T -e DATABASE_URL=postgresql+psycopg://ragforge:local-ragforge-change-me@db:5432/ragforge_m2_benchmark -e STORAGE_DIR=/tmp/m2-benchmark-uploads api python benchmarks/run.py --candidates --output /tmp/postgres-benchmark.json", "docker cp ragforge-m2-api-1:/tmp/postgres-benchmark.json benchmarks/results/postgres.json", "```", "", "Use the configured database password if it differs. Reuse the dedicated database after its creation; do not recreate or delete a live database. Canonical corpus/source/dependency hashes (UTF-8 without BOM, LF endings), dataset hash, model profile, environment, configuration, every question, retrieved passages, exact citations and metrics are retained in [postgres.json](../benchmarks/results/postgres.json) and [sqlite.json](../benchmarks/results/sqlite.json). Timing changes across runs; semantic retrieval results are the substantive comparison.", "", "Human review is explicit:", "", "```sh", "python benchmarks/review.py list", "python benchmarks/review.py show --id candidate-returns-01", "# A human inspects all proposed sources/answers; correct candidates.json if necessary.", "python benchmarks/review.py approve --id candidate-returns-01 --reviewer 'Your name' --notes 'Reviewed question, complete source and expected response'", "# Or use reject with a reason.", "```", "", "Approvals append a reviewer/timestamp/notes/source checksum/corpus checksum audit record and enter a separate `human_approved` split. Corpus changes invalidate prior approvals. The agent did not approve any candidate as a human. `python scripts/performance.py` reproduces the HTTP load test against the isolated semantic stack."]
(ROOT/"docs/BENCHMARKS.md").write_text("\n".join(lines)+"\n",encoding="utf-8",newline="\n")
print("Rendered docs/BENCHMARKS.md from executed JSON reports")
